#!/bin/sh
# agenteval sandbox-exec -- generated by agenteval, do not edit.
#
#   sandbox-exec <command> [args...]
#
# Runs the command inside a bubblewrap sandbox: read-only system, private /tmp
# and /run (host daemons' unix sockets stay out of reach), writable workspace
# and harness state dirs, configured paths hidden, own network namespace (only
# the Inspect model proxy is relayed in), no nested user namespaces, and an
# allow-listed environment. Fails closed: if bubblewrap cannot set up the
# sandbox the command is never run.
#
# Run it as an unprivileged user. As root the command keeps uid 0 of the parent
# user namespace, so root-owned IPC endpoints still visible in the read-only
# filesystem view stay reachable; that is a weaker boundary (a warning is printed).
#
# profile: @@PROFILE@@

set -u
set -f
sx_nl='
'
IFS=$sx_nl

# ------------------------------------------------------------- rendered profile
# Lists are newline separated. "~" in hide paths expands to the agent home and
# to the invoking user's home; in writable paths to the invoking user's home.
sx_network=@@NETWORK@@
sx_clear_env=@@CLEAR_ENV@@
sx_agent_home=@@AGENT_HOME@@
sx_workspace=@@WORKSPACE@@
sx_hide_paths=@@HIDE_PATHS@@
sx_writable_paths=@@WRITABLE_PATHS@@
sx_state_dirs=@@STATE_DIRS@@
sx_config_dirs=@@CONFIG_DIRS@@
sx_env_names=@@ENV_NAMES@@
sx_env_prefixes=@@ENV_PREFIXES@@
sx_proxy_dir=@@PROXY_DIR@@
sx_root_caps=@@ROOT_CAPS@@
sx_bwrap_group=@@BWRAP_GROUP@@

# ------------------------------------------------------------- runtime state
sx_mode=
sx_work=
sx_args=
sx_bwrap_pid=
sx_relay_pids=
sx_hidden=
sx_exposed=
sx_ports=

# Runs inside the sandbox as `sh -c "$sx_inner" sx-inner PROXY_DIR PORTS CMD...`.
# Signals a successful sandbox setup on fd 3, asserts CAP_SYS_ADMIN is gone,
# starts one TCP->unix relay per bridge port on the sandbox's loopback, then
# execs the command.
sx_inner='printf started >&3
exec 3>&- 4<&-
capeff=$(awk "/^CapEff:/ { print \$2 }" /proc/self/status 2>/dev/null)
if [ -n "$capeff" ] && [ $(( (0x$capeff >> 21) & 1 )) -ne 0 ]; then
    echo "agenteval sandbox-exec: the sandbox kept CAP_SYS_ADMIN; refusing to run the command" >&2
    exit 125
fi
proxy_dir=$1
ports=$2
shift 2
for port in $ports; do
    socat -d0 "TCP-LISTEN:$port,bind=127.0.0.1,fork,reuseaddr" "UNIX-CONNECT:$proxy_dir/$port.sock" </dev/null &
    hex=$(printf %04X "$port")
    tries=0
    until grep -q "0100007F:$hex 00000000:0000 0A " /proc/net/tcp 2>/dev/null; do
        tries=$((tries + 1))
        if [ "$tries" -ge 200 ]; then
            echo "agenteval sandbox-exec: model proxy relay on port $port did not start inside the sandbox" >&2
            exit 125
        fi
        sleep 0.05
    done
done
exec "$@"'

sx_die() {
    printf 'agenteval sandbox-exec: %s\n' "$1" >&2
    exit 125
}

# Append bubblewrap arguments (NUL separated; read by `bwrap --args 4`).
sx_arg() {
    printf '%s\0' "$@" >>"$sx_args" || sx_die "cannot write the bubblewrap argument file"
}

# sx_add LISTVAR VALUE: append VALUE to a newline list unless already present.
sx_add() {
    eval "sx_cur=\${$1}"
    case "$sx_nl$sx_cur$sx_nl" in
        *"$sx_nl$2$sx_nl"*) return 0 ;;
    esac
    if [ -z "$sx_cur" ]; then
        sx_cur=$2
    else
        sx_cur=$sx_cur$sx_nl$2
    fi
    eval "$1=\$sx_cur"
}

# sx_expand PATH HOME: expand a leading "~".
sx_expand() {
    case "$1" in
        "~") printf '%s\n' "$2" ;;
        "~/"*) printf '%s/%s\n' "${2%/}" "${1#"~/"}" ;;
        *) printf '%s\n' "$1" ;;
    esac
}

# sx_is_under PATH PARENT: PATH lies strictly below PARENT.
sx_is_under() {
    case "$1" in
        "${2%/}"/*) return 0 ;;
    esac
    return 1
}

sx_find_run_home() {
    sx_h=${HOME-}
    case "$sx_h" in
        /*) ;;
        *) sx_h=$(getent passwd "$(id -u)" 2>/dev/null | cut -d: -f6) ;;
    esac
    case "$sx_h" in
        /*) printf '%s\n' "$sx_h" ;;
        *) printf '%s\n' "$sx_agent_home" ;;
    esac
}

sx_env_allowed() {
    for sx_n in $sx_env_names; do
        if [ "$1" = "$sx_n" ]; then return 0; fi
    done
    for sx_p in $sx_env_prefixes; do
        case "$1" in
            "$sx_p"*) return 0 ;;
        esac
    done
    return 1
}

# --setenv for every allow-listed variable of the current environment.
sx_env_args() {
    for sx_name in $(env | sed -n 's/^\([A-Za-z_][A-Za-z0-9_]*\)=.*/\1/p' | sort -u); do
        sx_env_allowed "$sx_name" || continue
        eval "sx_isset=\${$sx_name+x}"
        [ -n "$sx_isset" ] || continue
        eval "sx_val=\${$sx_name}"
        sx_arg --setenv "$sx_name" "$sx_val"
    done
}

# sx_parse_port URL: port of a bridge URL on this machine (http://localhost:PORT/...).
sx_parse_port() {
    case "$1" in
        http://localhost:*|http://127.0.0.1:*) ;;
        *) return 1 ;;
    esac
    sx_rest=${1#http://*:}
    sx_pp=${sx_rest%%/*}
    case "$sx_pp" in
        ''|0*|*[!0-9]*) return 1 ;;
    esac
    if [ "${#sx_pp}" -gt 5 ] || [ "$sx_pp" -gt 65535 ]; then return 1; fi
    printf '%s\n' "$sx_pp"
}

# Collect the bridge ports into sx_ports.
sx_bridge_ports() {
    for sx_url in "${OPENAI_BASE_URL-}" "${ANTHROPIC_BASE_URL-}"; do
        sx_pp=$(sx_parse_port "$sx_url") || continue
        sx_add sx_ports "$sx_pp"
    done
}

sx_unix_listening() {
    if [ -r /proc/net/unix ]; then
        awk -v p="$1" '$NF == p && $4 == "00010000" { f = 1 } END { exit !f }' /proc/net/unix
    else
        [ -S "$1" ]
    fi
}

# sx_wait CMD...: poll CMD for up to ~10s.
sx_wait() {
    sx_tries=0
    until "$@"; do
        sx_tries=$((sx_tries + 1))
        if [ "$sx_tries" -ge 200 ]; then return 1; fi
        sleep 0.05
    done
}

# Full root: CAP_SYS_ADMIN (21) for the mounts and CAP_NET_ADMIN (12) for the
# loopback of the new network namespace.
sx_full_root() {
    [ "$(id -u)" = 0 ] || return 1
    sx_capeff=$(awk '/^CapEff:/ { print $2 }' /proc/self/status 2>/dev/null)
    [ -n "$sx_capeff" ] || return 1
    [ $(( (0x$sx_capeff >> 21) & (0x$sx_capeff >> 12) & 1 )) -eq 1 ]
}

# sx_reachable PATH: can the sandboxed identity traverse every parent of PATH?
# Only matters for root inside a user namespace, where just uid/gid 0 are mapped
# (other owners count as "other"); bwrap cannot mount below untraversable dirs.
sx_reachable() {
    [ "$sx_mode" = userns-root ] || return 0
    sx_d=${1%/*}
    while [ -n "$sx_d" ]; do
        sx_st=$(stat -c '%u:%g:%a' "$sx_d" 2>/dev/null) || return 1
        sx_u=${sx_st%%:*}
        sx_g=${sx_st#*:}
        sx_g=${sx_g%%:*}
        sx_m=$(( 0${sx_st##*:} ))
        if [ "$sx_u" = 0 ]; then
            [ $((sx_m & 64)) -ne 0 ] || return 1
        elif [ "$sx_g" = 0 ]; then
            [ $((sx_m & 8)) -ne 0 ] || return 1
        else
            [ $((sx_m & 1)) -ne 0 ] || return 1
        fi
        sx_d=${sx_d%/*}
    done
}

# sx_hide_args all|nested: hide existing paths (dirs -> empty tmpfs, files ->
# /dev/null). "nested" only re-hides paths below a writable/config bind.
sx_hide_args() {
    for sx_hp in $sx_hidden; do
        sx_reachable "$sx_hp" || continue
        if [ "$1" = nested ]; then
            sx_nested=
            for sx_ep in $sx_exposed; do
                if sx_is_under "$sx_hp" "$sx_ep"; then
                    sx_nested=1
                    break
                fi
            done
            [ -n "$sx_nested" ] || continue
        fi
        if [ -d "$sx_hp" ]; then
            sx_arg --tmpfs "$sx_hp"
        elif [ -e "$sx_hp" ]; then
            sx_arg --ro-bind /dev/null "$sx_hp"
        fi
    done
}

# network: host keeps DNS working when /etc/resolv.conf points into the hidden
# /run (systemd-resolved's stub-resolv.conf): re-bind just that file read-only.
sx_resolv_args() {
    sx_resolv=$(readlink -f /etc/resolv.conf 2>/dev/null) || sx_resolv=
    case "$sx_resolv" in
        /run/*) sx_arg --ro-bind-try "$sx_resolv" "$sx_resolv" ;;
    esac
}

# Background jobs of a non-interactive sh inherit SIGINT/SIGQUIT as ignored;
# restore the defaults for the sandboxed command when coreutils env can.
sx_exec_bwrap() {
    if env --default-signal=INT,QUIT true >/dev/null 2>&1; then
        exec env --default-signal=INT,QUIT bwrap "$@"
    fi
    exec bwrap "$@"
}

# A bwrap on PATH that this user may not execute (provision.sh restricts it).
sx_bwrap_on_path() {
    IFS=:
    for sx_pd in ${PATH-}; do
        if [ -f "${sx_pd:-.}/bwrap" ]; then
            IFS=$sx_nl
            printf '%s\n' "${sx_pd:-.}/bwrap"
            return 0
        fi
    done
    IFS=$sx_nl
    return 1
}

sx_cleanup() {
    if [ -n "$sx_bwrap_pid" ]; then kill "$sx_bwrap_pid" 2>/dev/null; fi
    for sx_pid in $sx_relay_pids; do
        kill "$sx_pid" 2>/dev/null
    done
    if [ -n "$sx_work" ]; then rm -rf "$sx_work"; fi
}

sx_main() {
    if [ "$#" -eq 0 ]; then sx_die "usage: sandbox-exec <command> [args...]"; fi
    sx_b=$(command -v bwrap 2>/dev/null) || sx_b=
    if [ -z "$sx_b" ] || [ ! -x "$sx_b" ]; then
        if sx_b=$(sx_bwrap_on_path); then
            sx_die "$sx_b is not executable for uid $(id -u) (only root and group $sx_bwrap_group may run it); refusing to run the command unsandboxed"
        fi
        sx_die "bubblewrap (bwrap) is not installed; refusing to run the command unsandboxed"
    fi

    trap sx_cleanup EXIT
    trap 'exit 129' HUP
    trap 'exit 130' INT
    trap 'exit 143' TERM

    sx_work=$(mktemp -d /tmp/agenteval-sx.XXXXXX) || sx_die "cannot create a private temp directory"
    sx_args=$sx_work/args
    : >"$sx_args" || sx_die "cannot create the bubblewrap argument file"

    if [ "$(id -u)" = 0 ]; then
        printf '%s\n' "agenteval sandbox-exec: warning: running as root (uid 0); root runs are a weaker boundary (root-owned IPC outside the sandbox stays reachable), use an unprivileged user" >&2
    fi

    sx_run_home=$(sx_find_run_home)
    sx_homes=
    sx_add sx_homes "$sx_agent_home"
    sx_add sx_homes "$sx_run_home"
    for sx_raw in $sx_hide_paths; do
        for sx_home in $sx_homes; do
            sx_add sx_hidden "$(sx_expand "$sx_raw" "$sx_home")"
        done
    done

    # namespaces + read-only system. Full root (e.g. in a VM) gets no user
    # namespace (so it can still use files of other users, like root outside) but
    # loses every capability that could undo the mounts. Everyone else, and root
    # without those capabilities (e.g. in a container), gets a user namespace in
    # which creating further (nested) user namespaces is disabled. Full root
    # cannot use --disable-userns (it needs --unshare-user); there only the host's
    # user-namespace policy (AppArmor/sysctl) limits nested namespaces.
    sx_arg --die-with-parent --new-session
    if sx_full_root; then
        sx_mode=root
        sx_arg --unshare-ipc --unshare-pid --unshare-net --unshare-uts --unshare-cgroup-try
        sx_arg --cap-drop ALL
        # only add capabilities root actually holds (bwrap misbehaves otherwise)
        for sx_cap in $sx_root_caps; do
            if [ $(( (0x$sx_capeff >> ${sx_cap#*:}) & 1 )) -eq 1 ]; then
                sx_arg --cap-add "${sx_cap%:*}"
            fi
        done
    elif [ "$(id -u)" = 0 ]; then
        sx_mode=userns-root
        sx_arg --unshare-all --unshare-user --disable-userns --cap-drop ALL
    else
        sx_mode=userns
        sx_arg --unshare-all --unshare-user --disable-userns
    fi
    if [ "$sx_network" = host ]; then sx_arg --share-net; fi
    # A network namespace does not isolate filesystem unix sockets, so /run (and
    # /var/run, a link to it) is replaced: host daemons (D-Bus, systemd,
    # resolved, docker) must not be reachable from inside.
    sx_arg --ro-bind / / --dev /dev --proc /proc --tmpfs /tmp --tmpfs /run
    if [ "$sx_network" = host ]; then sx_resolv_args; fi
    sx_hide_args all

    # writable: workspace, harness state dirs, extra paths; read-only: harness config
    sx_arg --bind "$sx_workspace" "$sx_workspace"
    sx_add sx_exposed "$sx_workspace"
    for sx_d in $sx_state_dirs; do
        sx_p=${sx_run_home%/}/$sx_d
        mkdir -p "$sx_p" 2>/dev/null
        sx_arg --bind-try "$sx_p" "$sx_p"
        sx_add sx_exposed "$sx_p"
    done
    for sx_raw in $sx_writable_paths; do
        sx_p=$(sx_expand "$sx_raw" "$sx_run_home")
        sx_arg --bind-try "$sx_p" "$sx_p"
        sx_add sx_exposed "$sx_p"
    done
    for sx_d in $sx_config_dirs; do
        sx_p=${sx_run_home%/}/$sx_d
        sx_arg --ro-bind-try "$sx_p" "$sx_p"
        sx_add sx_exposed "$sx_p"
    done
    sx_hide_args nested

    if [ "$sx_clear_env" = 1 ]; then
        sx_arg --clearenv
        sx_env_args
    fi

    # proxy-only network: relay each bridge port through a unix socket
    if [ "$sx_network" = proxy-only ]; then sx_bridge_ports; fi
    sx_inner_ports=
    if [ -n "$sx_ports" ]; then
        command -v socat >/dev/null 2>&1 \
            || sx_die "socat is not installed; cannot relay the model proxy into the sandbox"
        mkdir -m 700 "$sx_work/proxy" || sx_die "cannot create the proxy socket directory"
        sx_pdeath=
        if setpriv --pdeathsig TERM true >/dev/null 2>&1; then sx_pdeath=1; fi
        for sx_port in $sx_ports; do
            sx_sock=$sx_work/proxy/$sx_port.sock
            if [ -n "$sx_pdeath" ]; then
                setpriv --pdeathsig TERM \
                    socat -d0 "UNIX-LISTEN:$sx_sock,fork,mode=600" "TCP:127.0.0.1:$sx_port" </dev/null &
            else
                socat -d0 "UNIX-LISTEN:$sx_sock,fork,mode=600" "TCP:127.0.0.1:$sx_port" </dev/null &
            fi
            sx_add sx_relay_pids "$!"
            sx_wait sx_unix_listening "$sx_sock" \
                || sx_die "model proxy relay for port $sx_port did not start"
            sx_inner_ports="$sx_inner_ports $sx_port"
        done
        # read-only: connect() needs no write access; the sandbox must not add,
        # remove or replace entries next to the relay sockets
        sx_arg --ro-bind "$sx_work/proxy" "$sx_proxy_dir"
    fi

    # bwrap runs in the background so signals reach the traps; it keeps our stdin.
    if (: <&0) 2>/dev/null; then exec 5<&0; else exec 5</dev/null; fi
    sx_exec_bwrap --args 4 /bin/sh -c "$sx_inner" sx-inner "$sx_proxy_dir" "$sx_inner_ports" "$@" \
        3>"$sx_work/started" 4<"$sx_args" 0<&5 5<&- &
    sx_bwrap_pid=$!
    exec 5<&-
    wait "$sx_bwrap_pid"
    sx_rc=$?
    sx_bwrap_pid=
    if [ ! -s "$sx_work/started" ]; then
        sx_die "bubblewrap could not set up the sandbox (exit $sx_rc); the command was NOT run. \
Unprivileged user namespaces must be allowed (Ubuntu: AppArmor profile for bwrap; Docker: \
--security-opt seccomp=unconfined,apparmor=unconfined,systempaths=unconfined)."
    fi
    exit "$sx_rc"
}

sx_main "$@"
